function wp_json_encode($v){return json_encode($v);}function wp_mkdir_p($p){return mkdir($p,0700,true);}function sanitize_textarea_field($s){return trim(strip_tags($s));}
class SBS_Finishing {static $imports=0;static function error($c,$m,$status=422){return new WP_Error($c,$m);}static function import_fix($source,$preview,$title,$series,$job){self::$imports++;return array('uuid'=>$job,'approval'=>null);}}
class SBS_Final_Print {static function intact($a){return hash_file('sha256',$a['path'])===$a['sha256'];}}
class SBS_Storage {static $assets=array();static function ensure_directories(){return true;}static function base_dir(){return $GLOBALS['tmp'];}static function absolute_path($a){return $a['path'];}static function get_asset($id){return self::$assets[$id]??null;}static function store_bytes($bytes,$name,$mime,$owner,$owner_id,$role,$label,$meta=array()){$id=count(self::$assets)+1;$path=self::base_dir().'/'.$id.'.png';file_put_contents($path,$bytes);return self::$assets[$id]=array('id'=>$id,'path'=>$path,'mime'=>$mime,'sha256'=>hash('sha256',$bytes),'url'=>'/asset/'.$id,'role'=>$role);}}
